// Copyright (c) 2026 VEOR Browser Authors. All rights reserved.  #pragma once  #include <memory> #include <string>  #include “base/functional/callback.h” #include “base/memory/weak_ptr.h” #include “base/time/time.h”  namespace veor {  // ───────────────────────────────────────────────────────────────────────────── // UpdateChecker // ───────────────────────────────────────────────────────────────────────────── // Checks for browser updates via HTTP GET to a version endpoint. // // Silent check on startup. Toast notification if update available. // No auto-download. No restart. Just inform. // ─────────────────────────────────────────────────────────────────────────────  class UpdateChecker {  public:   UpdateChecker();   ~UpdateChecker();    // Current version (set at compile time)   static std::string GetCurrentVersion();    // Check for updates asynchronously. Calls |on_result| with true if update   // is available, false otherwise.   void CheckForUpdate(base::OnceCallback<void(bool update_available,                                                         const std::string& version)> on_result);    // Schedule periodic checks (every 24 hours)   void StartPeriodicChecks();   void StopPeriodicChecks();  private:   void OnCheckComplete(const std::string& response_body);   void ScheduleNextCheck();    base::Time last_check_time_;   bool periodic_checks_active_ = false;   base::OnceCallback<void(bool, const std::string&)> pending_callback_;    base::WeakPtrFactory<UpdateChecker> weak_factory_{this}; };  } // namespace veor
